test('P3 任职资格：标准版本严格匹配、未评定阻断、独立认证与证据快照不改任职',async()=>{
 const {sqlite,e}=await setup();const v1=await send({action:'standard',code:'QUAL',name:'质量实践能力',anchors});await send({action:'assessment',employeeId:e.id,standardId:v1.id,rating:5,evidence:'旧版能力标准的完整评估材料',assessedOn:'2026-01-01'});const v2=await send({action:'standard',code:'QUAL',name:'质量实践新版',anchors});const standard=await qual({action:'standard',code:'Q1',name:'质量工程内部资格',criteria:'依据质量实践新版能力标准达到三级',requirements:[{standardId:v2.id,target:3}]});act('employee');assert.ok(!(await get()).records.some(r=>r.id===standard.id));act('owner');await qual({action:'publishStandard',id:standard.id});act('employee');const app=await qual({action:'apply',standardId:standard.id,employeeId:e.id,evidence:'提交项目实践证明申请质量工程资格'});await qual({action:'review',id:app.id,accepted:true,evidence:'申请人不能自行评审资格'},403);act('manager');let d=await expect(await qualifications.GET());assert.equal(d.readiness.find(x=>x.id===app.id).items[0].rating,null);await qual({action:'review',id:app.id,accepted:true,evidence:'旧版本能力评分不能代替新版'},400);await send({action:'assessment',employeeId:e.id,standardId:v2.id,rating:3,evidence:'按新版标准核实案例与实践结果',assessedOn:'2026-02-01'});await qual({action:'review',id:app.id,accepted:true,evidence:'核对全部能力要求及评估证据通过',validUntil:'2099-12-31'});d=await get();const result=d.records.find(x=>x.id===app.id);assert.equal(result.status,'certified');assert.equal(result.payload.qualificationProof[0].rating,3);assert.ok(result.payload.certificateNumber.startsWith('IQ-'));
 await send({action:'assessment',employeeId:e.id,standardId:v2.id,rating:1,evidence:'后续新评估不应覆盖原认证证据',assessedOn:'2026-03-01'});assert.equal((await get()).records.find(x=>x.id===app.id).payload.qualificationProof[0].rating,3);act('employee');await qual({action:'apply',standardId:standard.id,employeeId:e.id,evidence:'有效期内不能重复申请同版本资格'},400);assert.equal((await expect(await hris.GET())).state.employees[0].job,e.job);act('hr');await qual({action:'revoke',id:app.id,evidence:'复核后撤销资格，原认证记录保留'});act('employee');assert.equal((await get()).records.find(x=>x.id===app.id).status,'revoked');sqlite.close();
});
test('P3 任职资格：HR代办不得自审、跨组织拒绝、停用阻止新申请与撤回',async()=>{
 const {sqlite,e,other}=await setup();const cap=await send({action:'standard',code:'Q-SCOPE',name:'资格范围能力',anchors});const standard=await qual({action:'standard',code:'Q2',name:'内部资格范围验证',criteria:'具备可复核的一级实践证据',requirements:[{standardId:cap.id,target:1}]});await qual({action:'publishStandard',id:standard.id});act('hr');await qual({action:'apply',standardId:standard.id,employeeId:other.id,evidence:'跨组织不能代办资格申请'},403);const app=await qual({action:'apply',standardId:standard.id,employeeId:e.id,evidence:'HR根据员工书面申请代为登记'});await qual({action:'review',id:app.id,accepted:false,evidence:'代办者不能同时承担独立评审'},403);act('employee');await qual({action:'withdraw',id:app.id,evidence:'非提交人不得撤回HR代办申请'},403);act('hr');await qual({action:'withdraw',id:app.id,evidence:'根据原申请人说明撤回代办申请'});await qual({action:'archiveStandard',id:standard.id});act('employee');await qual({action:'apply',standardId:standard.id,employeeId:e.id,evidence:'停用标准不得继续新申请'},400);act('approver');assert.ok(!(await get()).records.some(r=>r.id===app.id));sqlite.close();
});

