test('P3 实名问卷：版本快照、名单冻结、本人填报、修改撤回及结项锁定',async()=>{
 const {sqlite,e,other,org}=await setup();const questions=[{type:'rating',prompt:'培训内容对工作的帮助程度',lowLabel:'帮助很小',highLabel:'帮助很大'},{type:'choice',prompt:'更适合的学习形式',options:['现场练习','在线案例']}];const template=await survey({action:'template',code:'S1',name:'培训反馈',description:'收集实名培训反馈用于改进后续课程',questions});act('employee');assert.ok(!(await get()).records.some(r=>r.id===template.id));act('owner');await survey({action:'publishTemplate',id:template.id});const round=await survey({action:'round',templateId:template.id,name:'本期培训反馈',orgId:org.id,start:'2020-01-01',end:'2099-12-31',purpose:'实名收集课程反馈，仅项目HR及管理员查看答卷'});await survey({action:'open',id:round.id});await survey({action:'template',code:'S1',name:'培训反馈新版',description:'新版模板不会更改已有问卷题目',questions:[{...questions[0],prompt:'新版问题'}]});assert.equal((await get()).records.find(r=>r.id===round.id).payload.surveyQuestions.length,2);
 await core({action:'employee',code:'LATE',name:'发布后新加入人员',orgId:org.id,job:'测试',level:'',email:'',joined:'2026-01-01'});const late=(await expect(await hris.GET())).state.employees.find(x=>x.code==='LATE');await grant('late','employee',late.id);act('late');await survey({action:'respond',roundId:round.id,answers:[5,1]},403);assert.ok(!(await get()).records.some(r=>r.id===round.id));act('owner');await grant('outside','employee',other.id);act('outside');await survey({action:'respond',roundId:round.id,answers:[5,1]},403);
 act('employee');let d=await expect(await surveys.GET());assert.equal(d.records.find(r=>r.id===round.id).payload.participantIds,undefined);assert.equal(d.summaries.length,0);const hist=await expect(await dev.GET(request('/api/development?id='+round.id)));assert.ok(hist.items.every(x=>x.snapshot.payload.participantIds===undefined));await survey({action:'respond',roundId:round.id,answers:[0,1]},400);await survey({action:'respond',roundId:round.id,answers:[5]},400);const response=await survey({action:'respond',roundId:round.id,answers:[5,1]});const changed=await survey({action:'respond',roundId:round.id,answers:[3,0]});assert.equal(changed.id,response.id);assert.equal((await expect(await selfService.GET())).tasks.filter(t=>t.kind==='surveyRound').length,0);
 act('hr');d=await expect(await surveys.GET());assert.equal(d.summaries[0].invited,1);assert.equal(d.summaries[0].responded,1);assert.equal(d.summaries[0].questions[0].average,3);await survey({action:'respond',roundId:round.id,answers:[1,0]},403);act('employee');await survey({action:'withdrawResponse',id:response.id,evidence:'核实填写内容后先撤回答卷'});assert.equal((await expect(await selfService.GET())).tasks.filter(t=>t.kind==='surveyRound').length,1);act('hr');d=await expect(await surveys.GET());assert.equal(d.summaries[0].questions[0].average,null);assert.equal(d.summaries[0].responded,0);act('employee');await survey({action:'respond',roundId:round.id,answers:[4,1]});act('hr');await survey({action:'close',id:round.id,evidence:'本期实名问卷回收完毕结项'});act('employee');await survey({action:'respond',roundId:round.id,answers:[1,0]},400);await survey({action:'withdrawResponse',id:response.id,evidence:'结项之后不允许撤回答卷'},400);act('manager');assert.ok(!(await get()).records.some(r=>r.id===response.id));sqlite.close();
});

