test('P3 干部：提名独立审议、真实调动前置、任用核对与本人述职独立核验',async()=>{
 const {sqlite,e,position}=await setup();await core({action:'workflow',kind:'transfer',steps:[{userId:'manager',name:'调出方'},{userId:'approver',name:'调入方'}]});const n=await cadre({action:'nominate',employeeId:e.id,positionId:position.id,evidence:'根据岗位职责和实践情况发起提名'});await cadre({action:'decide',id:n.id,accepted:true,evidence:'不能审议自己发起的提名'},403);act('employee');assert.ok(!(await get()).records.some(r=>r.id===n.id));act('manager');await cadre({action:'decide',id:n.id,accepted:true,evidence:'独立核实岗位要求及候选依据后通过'});act('owner');await cadre({action:'recordAppointment',id:n.id,approvalId:'missing',evidence:'未完成岗位调动不能核对任用'},400);assert.equal((await expect(await hris.GET())).state.employees.find(x=>x.id===e.id).positionId??null,null);
 await core({action:'request',employeeId:e.id,kind:'transfer',effectiveOn:businessDate(),orgId:position.orgId,positionId:position.id,reason:'干部提名审议通过，申请正式岗位调动'});const approval=(await expect(await hris.GET())).state.approvals.find(a=>a.employeeId===e.id&&a.status==='pending');await cadre({action:'recordAppointment',id:n.id,approvalId:approval.id,evidence:'待审批调动不能当作任用完成'},400);act('manager');await core({action:'decide',id:approval.id,decision:'approved'});act('approver');await core({action:'decide',id:approval.id,decision:'approved'});act('owner');await core({action:'executeTransfer',id:approval.id});await cadre({action:'recordAppointment',id:n.id,approvalId:approval.id,evidence:'核对终审调动及当前岗位一致'});await cadre({action:'recordAppointment',id:n.id,approvalId:approval.id,evidence:'同一任用不能重复核对'},400);const observation=await cadre({action:'observation',nominationId:n.id,due:'2099-12-31',objectives:'完成岗位工作目标，提供真实业务成果并接受核验'});await cadre({action:'submitReview',id:observation.id,evidence:'HR不能冒充员工提交述职'},403);act('employee');assert.ok((await expect(await selfService.GET())).tasks.some(t=>t.id===observation.id));await cadre({action:'submitReview',id:observation.id,evidence:'已完成约定工作目标并提供项目验收依据'});act('owner');await cadre({action:'completeReview',id:observation.id,accepted:true,evidence:'发起考察者不能自行独立核验'},403);act('manager');await cadre({action:'returnReview',id:observation.id,evidence:'请补充目标达成的数据记录'});act('employee');await cadre({action:'submitReview',id:observation.id,evidence:'补充完整项目记录及成果验证材料'});act('manager');await cadre({action:'completeReview',id:observation.id,accepted:true,evidence:'复核目标及材料，确认考察目标达成'});assert.equal((await get()).records.find(x=>x.id===observation.id).status,'completed');assert.equal((await expect(await hris.GET())).state.employees.find(x=>x.id===e.id).status,e.status);sqlite.close();
});

