test('P3 培训场次：排期冲突、必修出勤门槛、独立核验、补充记录与学习结项',async()=>{
 const {sqlite,e,org}=await setup();const course=await send({action:'course',code:'CLASS',title:'线下实践课程',description:'完成现场实践并提交成果进行核验',content:'依据现场演练任务完成案例分析，提交可以核实的工作成果。'});await send({action:'publishCourse',id:course.id});const training=await send({action:'training',name:'线下实践项目',orgId:org.id,period:'2026',start:'2020-01-01',end:'2099-12-31',instructor:'测试讲师',courseIds:[course.id]});await send({action:'publishTraining',id:training.id});const scheduled={action:'session',trainingId:training.id,courseId:course.id,title:'现场演练一',startAt:'2026-01-02T09:00:00+08:00',endAt:'2026-01-02T12:00:00+08:00',location:'测试教室A',instructor:'测试讲师A',mandatory:true};const s=await session(scheduled);await session({...scheduled,title:'冲突场次'},400);act('employee');assert.ok(!(await get()).records.some(x=>x.id===s.id));const enrolled=await send({action:'enroll',trainingId:training.id,employeeId:e.id,courseId:course.id,due:'2099-12-31'});assert.ok((await expect(await trainingSessions.GET())).records.some(x=>x.id===s.id));await send({action:'submitLearning',id:enrolled.id,evidence:'已完成线下案例并提交成果待核验'});act('manager');await send({action:'verifyLearning',id:enrolled.id,accepted:true,evidence:'必修出勤尚无记录不能完成课程'},400);
 act('owner');const attendance=await session({action:'recordAttendance',sessionId:s.id,employeeId:e.id,present:false,evidence:'初始点名记录显示未出席待复核'});await session({action:'verifyAttendance',id:attendance.id,accepted:true,evidence:'出勤登记人不能自己核验'},403);act('manager');await session({action:'verifyAttendance',id:attendance.id,accepted:true,evidence:'核验初次点名记录确认为未出席'});await send({action:'verifyLearning',id:enrolled.id,accepted:true,evidence:'未出席不能满足必修场次'},400);
 act('employee');const updated=await session({action:'declare',sessionId:s.id,evidence:'补充实际参加现场练习的签到与成果材料'});assert.equal(updated.id,attendance.id);await session({action:'verifyAttendance',id:attendance.id,accepted:true,evidence:'本人不能核验自己的出席依据'},403);act('owner');await session({action:'closeSession',id:s.id,evidence:'存在待核验出勤不能直接结项'},400);act('manager');await session({action:'verifyAttendance',id:attendance.id,accepted:true,evidence:'核验补充材料，确认参加现场演练'});await send({action:'verifyLearning',id:enrolled.id,accepted:true,evidence:'必修出席与学习成果均完成核验'});act('employee');await session({action:'declare',sessionId:s.id,evidence:'已完成学习后不得再重写出勤'},400);act('owner');await session({...scheduled,title:'追加必修场次',startAt:'2026-01-03T09:00:00+08:00',endAt:'2026-01-03T12:00:00+08:00'},400);await session({action:'cancelSession',id:s.id,evidence:'已有确认出席不能直接取消'},400);await send({action:'closeTraining',id:training.id},400);await session({action:'closeSession',id:s.id,evidence:'出勤核验与现场材料归档完成'});await send({action:'closeTraining',id:training.id});assert.equal((await get()).records.find(x=>x.id===training.id).status,'closed');sqlite.close();
});

