test('P3 讲师试讲：取消不能绕过门槛、失败重试、截止日及冻结审计回滚',async()=>{
 const {sqlite,e,other,org}=await setup();await core({action:'employee',name:'合成第三员工',code:'TRIAL-C',orgId:org.id,job:'工程师',level:'',joined:'2020-01-01',email:''});const j=(await expect(await hris.GET())).state.employees.find(e=>e.code==='TRIAL-C');await grant('trialJudgeB','employee',other.id);await grant('trialJudgeC','employee',j.id);const p=await directory({action:'nominate',employeeId:e.id,title:'测试讲师',description:'以试讲通过结果办理入册',evidence:'合成活动材料用于失败分支测试'});const input={action:'arrange',profileId:p.id,title:'合成试讲重试',criteria:'合成评价标准固定100分，所有指定评委等权平均，80分通过。',participantIds:[other.id,j.id],passingScore:80,due,evidence:'合成指定评委与评价标准依据'};const first=await trial(input);await directory({action:'withdraw',id:p.id,evidence:'存在进行中试讲不能直接撤回提名'},400);await trial({action:'cancel',id:first.id,evidence:'安排需要重新核对，取消本次试讲'});act('hr');await directory({action:'review',id:p.id,accepted:true,evidence:'取消试讲不能跳过曾安排的试讲门槛'},400);act('owner');const second=await trial(input);act('trialJudgeB');const ctx=await (await import('../lib/hris/development-repository.ts')).developmentContext();assert.throws(()=>(awaitedApply(ctx,{action:'score',id:second.id,score:80,evidence:'截止日后不能提交新的评分'},'2100-01-01T00:00:00Z')),/截止日/);
 await trial({action:'score',id:second.id,score:70,evidence:'独立评价尚未达到活动要求'});act('trialJudgeC');await trial({action:'score',id:second.id,score:79,evidence:'另一评委根据标准独立评分'});act('hr');const revision=(await get()).revision;sqlite.exec("CREATE TRIGGER reject_trial_audit BEFORE INSERT ON hris_audit_events BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");await trial({action:'freeze',id:second.id,evidence:'审计失败不能发布试讲结果'},503);assert.equal((await get()).revision,revision);assert.equal((await get()).records.find(r=>r.id===second.id).status,'active');sqlite.exec('DROP TRIGGER reject_trial_audit');await trial({action:'freeze',id:second.id,evidence:'核对全部评分后独立冻结结果'});assert.equal((await get()).records.find(r=>r.id===second.id).payload.passed,false);await directory({action:'review',id:p.id,accepted:true,evidence:'最新试讲未通过不能办理入册'},400);act('owner');const third=await trial(input);await trial({action:'cancel',id:third.id,evidence:'旧修订号不能取消重新安排的试讲'},409,revision);act('trialJudgeB');await trial({action:'score',id:third.id,score:80,evidence:'新一轮按固定标准进行独立评分'});act('trialJudgeC');await trial({action:'score',id:third.id,score:80,evidence:'另一名评委独立评定达到要求'});act('hr');await trial({action:'freeze',id:third.id,evidence:'全体评分齐备，独立冻结通过结果'});await directory({action:'review',id:p.id,accepted:true,evidence:'采用最新冻结通过的试讲结果入册'});const d=await get();assert.equal(d.records.find(r=>r.id===p.id).payload.trialId,third.id);assert.equal(d.records.find(r=>r.id===third.id).payload.version,3);assert.equal(d.records.find(r=>r.id===second.id).payload.score,74.5);sqlite.close();
});
const {applyInstructorTrial:trialApply}=await import('../lib/hris/instructor-trials.ts');
function awaitedApply(ctx,command,at){return trialApply(ctx.records,ctx.state,ctx.member,command,at);}

const instructorCampaigns=await import('../app/api/instructor-campaigns/route.ts');
async function campaign(command,status=200,revision){const d=await expect(await instructorCampaigns.GET());return expect(await instructorCampaigns.POST(request('/api/instructor-campaigns',{revision:revision??d.revision,command})),status);}
test('P3 认证报名：范围与本人隔离、停止报名后续办、资格提名试讲入册完整关联',async()=>{
 const {sqlite,e,other,org}=await setup();const c=await campaign({action:'create',title:'内部讲师认证活动',orgId:org.id,instructorLevel:'合成一级',description:'组织管理与岗位实践教学',criteria:'报名人应具备岗位实践经验与教学案例，资格复核后参加独立试讲。',start:'2026-01-01',end:due,evidence:'合成活动制度与报名条件依据'});act('employee');assert.ok(!(await expect(await instructorCampaigns.GET())).records.some(r=>r.id===c.id));await campaign({action:'publish',id:c.id},403);act('owner');await campaign({action:'publish',id:c.id});act('employee');const a=await campaign({action:'apply',campaignId:c.id,evidence:'SECRET_APPLICATION 本人岗位实践及教学案例材料'});await campaign({action:'apply',campaignId:c.id,evidence:'重复报名不应重复进入资格复核'},400);act('manager');assert.ok(!(await expect(await instructorCampaigns.GET())).records.some(r=>r.id===a.id));await campaign({action:'review',id:a.id,accepted:true,evidence:'普通经理不能代替HR复核报名'},403);await grant('employee','hr',e.id,[org.id],true);act('employee');await campaign({action:'review',id:a.id,accepted:true,evidence:'本人即使有HR权限也不能自审'},403);await grant('employee','employee',e.id,[],true);act('hr');assert.ok((await queue()).items.some(r=>r.recordId===a.id));await campaign({action:'review',id:a.id,accepted:true,evidence:'独立核对报名条件和材料，资格通过'});act('owner');await campaign({action:'closeSignup',id:c.id,evidence:'停止接收新报名，已有报名继续办理'});act('hr');const p=await directory({action:'nominate',employeeId:e.id,instructorApplicationId:a.id,title:'伪造等级不得覆盖活动',description:'伪造条件不得覆盖已经固定的活动规则',evidence:'依据已独立通过报名创建提名'});let d=await get();assert.equal(d.records.find(r=>r.id===p.id).payload.title,'合成一级');assert.equal(d.records.find(r=>r.id===p.id).payload.requiresTrial,true);act('owner');await directory({action:'review',id:p.id,accepted:true,evidence:'活动提名没有完成试讲不能入册'},400);act('employee');await campaign({action:'withdraw',id:a.id,evidence:'已关联提名的报名不能再撤回'},400);d=await expect(await instructorCampaigns.GET());assert.ok(d.records.some(r=>r.kind==='instructorProfile'&&r.payload.instructorApplicationId===a.id));act('owner');
 await core({action:'employee',name:'合成报名评委',code:'CAMPAIGN-J',orgId:org.id,job:'工程师',level:'',joined:'2020-01-01',email:''});const j=(await expect(await hris.GET())).state.employees.find(e=>e.code==='CAMPAIGN-J');await grant('campaignJudge','employee',j.id);await grant('campaignJudgeOther','employee',other.id);const t=await trial({action:'arrange',profileId:p.id,title:'报名关联试讲',criteria:'根据活动核定标准以100分综合评价，80分通过，评委等权平均。',participantIds:[j.id,other.id],passingScore:80,due,evidence:'为已通过报名的提名安排试讲'});act('campaignJudge');await trial({action:'score',id:t.id,score:85,evidence:'独立核实案例及试讲表现后评分'});act('campaignJudgeOther');await trial({action:'score',id:t.id,score:87,evidence:'另一位指定评委独立提交评分'});act('hr');await trial({action:'freeze',id:t.id,evidence:'全部评分齐备后独立冻结结果'});act('owner');await directory({action:'review',id:p.id,accepted:true,evidence:'独立核对报名资格与冻结试讲结果入册'});d=await get();assert.equal(d.records.find(r=>r.id===p.id).status,'active');assert.equal(d.records.find(r=>r.id===p.id).payload.trialId,t.id);assert.equal(d.records.find(r=>r.id===c.id).status,'closed');const reports=await import('../app/api/reports/route.ts');let report=await expect(await reports.GET(request('/api/reports?dataset=instructorCampaignProgress')));assert.deepEqual(report.rows[0].slice(3),[1,0,1,0,0,1,1,1,0]);act('manager');await expect(await reports.GET(request('/api/reports?dataset=instructorCampaignProgress')),403);act('employee');await expect(await reports.GET(request('/api/reports?dataset=instructorCampaignProgress')),403);sqlite.close();
});
test('P3 认证报名：时间窗口、跨组织、撤回重报与资格审计失败回滚',async()=>{
 const {sqlite,e,other,org,otherOrg}=await setup();const input={action:'create',title:'报名边界活动',orgId:org.id,instructorLevel:'测试级别',description:'岗位实践与业务能力教学',criteria:'报名资格由独立HR根据活动条件与员工提交材料核对。',start:'2026-01-01',end:due,evidence:'合成活动用于边界与事务验证'};await campaign({...input,start:'2026-02-30'},400);act('hr');await campaign({...input,orgId:otherOrg.id},403);act('owner');const c=await campaign(input);await campaign({action:'publish',id:c.id});await grant('outsideApplicant','employee',other.id);act('outsideApplicant');assert.ok(!(await expect(await instructorCampaigns.GET())).records.some(r=>r.id===c.id));await campaign({action:'apply',campaignId:c.id,evidence:'范围外员工不能申请活动'},403);act('employee');const ctx=await (await import('../lib/hris/development-repository.ts')).developmentContext(),rules=await import('../lib/hris/instructor-campaigns.ts');assert.throws(()=>rules.applyInstructorCampaign(ctx.records,ctx.state,ctx.member,{action:'apply',campaignId:c.id,evidence:'报名开始日前不能提交申请'},'2025-12-31T00:00:00Z'),/报名期间/);assert.throws(()=>rules.applyInstructorCampaign(ctx.records,ctx.state,ctx.member,{action:'apply',campaignId:c.id,evidence:'报名截止日后不能提交申请'},'2100-01-01T00:00:00Z'),/报名期间/);const a=await campaign({action:'apply',campaignId:c.id,evidence:'报名材料需要补充后再次提交'});await campaign({action:'withdraw',id:a.id,evidence:'本人撤回补充材料后重新报名'});const b=await campaign({action:'apply',campaignId:c.id,evidence:'已补充报名材料，重新申请资格复核'});act('hr');const revision=(await get()).revision;sqlite.exec("CREATE TRIGGER reject_campaign_audit BEFORE INSERT ON hris_audit_events BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");await campaign({action:'review',id:b.id,accepted:true,evidence:'审计失败不得将资格变为通过'},503);assert.equal((await get()).revision,revision);assert.equal((await get()).records.find(r=>r.id===b.id).status,'submitted');sqlite.exec('DROP TRIGGER reject_campaign_audit');await campaign({action:'closeSignup',id:c.id,evidence:'停止新的申请，保留已有报名审核'});act('employee');await campaign({action:'withdraw',id:b.id,evidence:'停止报名后仍可撤回本人未关联申请'});await campaign({action:'apply',campaignId:c.id,evidence:'活动停止报名后不能重新报名'},400);act('hr');const draft=await campaign({...input,title:'取消草稿测试'});await campaign({action:'cancelDraft',id:draft.id,evidence:'草稿方案调整，不再发布报名'});await campaign({action:'publish',id:draft.id},400);sqlite.close();
});
test('P3 认证活动组织层级：下级HR可核对上级活动的本部门报名，不能管理上级活动',async()=>{
 const {sqlite,org}=await setup();await core({action:'org',name:'研发子部门',parentId:org.id,city:'上海',leader:'',status:'启用'});let s=(await expect(await hris.GET())).state;const child=s.orgs.find(o=>o.name==='研发子部门');await core({action:'employee',name:'合成下级员工',code:'CAMPAIGN-CHILD',orgId:child.id,job:'工程师',level:'',joined:'2020-01-01',email:''});s=(await expect(await hris.GET())).state;const e=s.employees.find(e=>e.code==='CAMPAIGN-CHILD');await grant('childApplicant','employee',e.id);await grant('childHr','hr',null,[child.id]);const c=await campaign({action:'create',title:'上级组织认证活动',orgId:org.id,instructorLevel:'一级',description:'组织与岗位业务实践教学',criteria:'含下级组织员工自主报名，提交实践材料，由本部门HR独立核对。',start:'2026-01-01',end:due,evidence:'合成上级活动对下级开放依据'});act('childHr');assert.ok(!(await expect(await instructorCampaigns.GET())).records.some(r=>r.id===c.id));act('owner');await campaign({action:'publish',id:c.id});act('childApplicant');const a=await campaign({action:'apply',campaignId:c.id,evidence:'本人提交岗位实践与教学案例材料'});act('childHr');let d=await expect(await instructorCampaigns.GET());assert.ok(d.records.some(r=>r.id===c.id));assert.ok(!d.managedOrgIds.includes(org.id));await campaign({action:'closeSignup',id:c.id,evidence:'下级HR无权停止整个上级活动'},403);await campaign({action:'review',id:a.id,accepted:true,evidence:'本部门HR独立核对本部门员工材料'});assert.equal((await get()).records.find(r=>r.id===a.id).status,'approved');sqlite.close();
});

