test('P3 认证培养：真实学习任务引用、必修核验前置、本人和组织隔离及入册快照',async()=>{
 const {sqlite,e,other,org,otherOrg}=await setup();const course=await send({action:'course',code:'INSTRUCTOR-DEV',title:'教学实践培养',description:'用于合成内部讲师培养的实践课程',content:'阅读教学案例，完成实践任务，提交证据并由独立管理者核验学习成果。'});await send({action:'publishCourse',id:course.id});const enrollment=await send({action:'enroll',employeeId:e.id,courseId:course.id,due});const otherEnrollment=await send({action:'enroll',employeeId:other.id,courseId:course.id,due});const p=await directory({action:'nominate',employeeId:e.id,title:'培养测试讲师',description:'教学实践与工作方法培训',evidence:'合成提名依据，关联真实培养任务'});await cultivation({action:'link',profileId:p.id,enrollmentId:otherEnrollment.id,mandatory:true,evidence:'不同员工学习任务不得关联'},400);act('employee');await cultivation({action:'link',profileId:p.id,enrollmentId:enrollment.id,mandatory:true,evidence:'本人不能给自己的提名配置培养'},403);act('hr');const link=await cultivation({action:'link',profileId:p.id,enrollmentId:enrollment.id,mandatory:true,evidence:'按培养计划把现有任务设为必修'});await cultivation({action:'link',profileId:p.id,enrollmentId:enrollment.id,mandatory:true,evidence:'同一任务不能重复关联同一提名'},400);await directory({action:'review',id:p.id,accepted:true,evidence:'必修学习没有完成不能入册'},400);act('manager');assert.ok(!(await expect(await instructorDevelopment.GET())).records.some(r=>r.id===link.id));await expect(await dev.GET(request('/api/development?id='+link.id)),403);await grant('outsideCultivation','hr',null,[otherOrg.id]);act('outsideCultivation');assert.ok(!(await expect(await instructorDevelopment.GET())).records.some(r=>r.id===link.id));await cultivation({action:'remove',id:link.id,evidence:'范围外HR不能移除培养要求'},403);act('employee');await send({action:'submitLearning',id:enrollment.id,evidence:'提交合成教学实践成果供独立核验'});act('hr');await directory({action:'review',id:p.id,accepted:true,evidence:'只有提交而未核验仍不得入册'},400);act('manager');await send({action:'verifyLearning',id:enrollment.id,accepted:true,evidence:'独立核实教学实践证据后认定完成'});act('hr');await directory({action:'review',id:p.id,accepted:true,evidence:'独立核对必修培养已完成，确认入册'});const d=await get();assert.equal(d.records.find(r=>r.id===p.id).payload.developmentProof[0].enrollmentId,enrollment.id);assert.equal(d.records.find(r=>r.id===p.id).payload.developmentProof[0].status,'completed');await cultivation({action:'remove',id:link.id,evidence:'入册后不能改写当时的培养关联'},400);assert.equal(d.records.find(r=>r.id===enrollment.id).status,'completed');sqlite.close();
});
test('P3 认证培养：取消任务不算完成、参考任务不阻断、关联移除审计与修订保护',async()=>{
 const {sqlite,e}=await setup();const courses=[];for(const code of ['DEV-REQUIRED','DEV-OPTIONAL']){const c=await send({action:'course',code,title:code,description:'合成培养任务用于取消与参考要求验证',content:'完成课程案例和教学实践，提交证据后由独立管理者核验，保留原过程。'});await send({action:'publishCourse',id:c.id});courses.push(c);}const mandatory=await send({action:'enroll',employeeId:e.id,courseId:courses[0].id,due}),optional=await send({action:'enroll',employeeId:e.id,courseId:courses[1].id,due});const p=await directory({action:'nominate',employeeId:e.id,title:'调整培养讲师',description:'工作案例与沟通方法教学',evidence:'合成培养安排用于必要边界验证'});const a=await cultivation({action:'link',profileId:p.id,enrollmentId:mandatory.id,mandatory:true,evidence:'原计划将此任务作为必修培养'});const old=(await get()).revision;await cultivation({action:'link',profileId:p.id,enrollmentId:optional.id,mandatory:false,evidence:'此任务仅参考，不作为入册前置'});await cultivation({action:'remove',id:a.id,evidence:'旧版本请求不能移除必修关联'},409,old);await send({action:'cancelEnrollment',id:mandatory.id,reason:'培养计划调整取消原学习任务'});act('hr');await directory({action:'review',id:p.id,accepted:true,evidence:'取消必修任务不能当作已经完成'},400);const revision=(await get()).revision;sqlite.exec("CREATE TRIGGER reject_cultivation_audit BEFORE INSERT ON hris_audit_events BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");await cultivation({action:'remove',id:a.id,evidence:'审计失败不得移除必修培养要求'},503);assert.equal((await get()).revision,revision);assert.equal((await get()).records.find(r=>r.id===a.id).status,'active');sqlite.exec('DROP TRIGGER reject_cultivation_audit');await cultivation({action:'remove',id:a.id,evidence:'核实培养计划已调整，不再要求此课程'});await directory({action:'review',id:p.id,accepted:true,evidence:'已核对培养安排，仅保留参考任务，确认入册'});const d=await get();assert.equal(d.records.find(r=>r.id===mandatory.id).status,'cancelled');assert.equal(d.records.find(r=>r.id===optional.id).status,'active');assert.equal(d.records.find(r=>r.id===p.id).payload.developmentProof.length,1);assert.equal(d.records.find(r=>r.id===p.id).payload.developmentProof[0].mandatory,false);sqlite.close();
});

