test('P3 补卡版本与撤回：独立核验、原记录保留、最新版本和回滚',async()=>{
 const {sqlite,e,otherOrg}=await setup();const shift=await attend({action:'shift',employeeId:e.id,date:'2026-01-05',name:'版本核验班次',startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00'});act('employee');const input={action:'correction',shiftId:shift.id,inAt:'2026-01-05T09:00:00+08:00',outAt:'2026-01-05T18:00:00+08:00',evidence:'合成门禁和项目记录证明当日出勤'};const withdrawn=await attend(input);act('manager');await attend({action:'withdrawCorrection',id:withdrawn.id,reason:'非本人或HR不得撤回员工补卡'},403);act('employee');await attend({action:'withdrawCorrection',id:withdrawn.id,reason:'原依据需要补充，先撤回本次补卡'});act('manager');await attend({action:'decideCorrection',id:withdrawn.id,accepted:true,evidence:'撤回记录不可继续批准'},400);act('employee');const first=await attend(input);act('manager');await attend({action:'decideCorrection',id:first.id,accepted:true,evidence:'核实当日第一版补卡依据并批准'});let d=await expect(await attendance.GET());assert.equal(d.report[0].correctionVersion,1);assert.equal(d.report[0].uncoveredMinutes,0);act('employee');await attend({action:'withdrawCorrection',id:first.id,reason:'已批准记录不能借待审撤回改变'},400);const second=await attend({...input,inAt:'2026-01-05T10:00:00+08:00',evidence:'补充证据表明当日实际十点开始工作'});d=await expect(await attendance.GET());assert.equal(d.report[0].correctionVersion,1);act('manager');const revision=(await get()).revision;sqlite.exec("CREATE TRIGGER reject_correction_audit BEFORE INSERT ON hris_audit_events BEGIN SELECT RAISE(ABORT,'audit unavailable'); END");await attend({action:'decideCorrection',id:second.id,accepted:true,evidence:'审计失败不得切换有效补卡版本'},503);assert.equal((await get()).revision,revision);assert.equal((await expect(await attendance.GET())).report[0].correctionVersion,1);sqlite.exec('DROP TRIGGER reject_correction_audit');await attend({action:'decideCorrection',id:second.id,accepted:true,evidence:'重新核实更完整的证据，批准新版补卡'});d=await expect(await attendance.GET());assert.equal(d.report[0].correctionVersion,2);assert.equal(d.report[0].uncoveredMinutes,60);assert.equal(d.records.find(r=>r.id===second.id).payload.supersedes,first.id);assert.equal(d.records.find(r=>r.id===first.id).payload.inAt,input.inAt);act('owner');const behalf=await attend(input);act('employee');await attend({action:'withdrawCorrection',id:behalf.id,reason:'员工本人撤回HR代为提交的待核验补卡'});assert.equal((await expect(await attendance.GET())).report[0].correctionVersion,2);await grant('outsideCorrection','hr',null,[otherOrg.id]);act('outsideCorrection');await attend({action:'withdrawCorrection',id:behalf.id,reason:'跨组织HR不能撤回其他范围补卡'},403);await expect(await dev.GET(request('/api/development?id='+second.id)),403);sqlite.close();
});
test('P3 补卡历史冲突：同时间不同事实不猜测、等价时区与新版本消除歧义',async()=>{
 const {sqlite,e}=await setup();const shift=await attend({action:'shift',employeeId:e.id,date:'2026-01-05',name:'历史冲突班次',startAt:'2026-01-05T09:00:00+08:00',endAt:'2026-01-05T18:00:00+08:00'});act('employee');const pending=await attend({action:'correction',shiftId:shift.id,inAt:'2026-01-05T10:00:00+08:00',outAt:'2026-01-05T18:00:00+08:00',evidence:'新的完整证据用于消除历史补卡冲突'});act('manager');const ctx=await (await import('../lib/hris/development-repository.ts')).developmentContext(),rules=await import('../lib/hris/attendance.ts'),base=ctx.records.find(r=>r.id===pending.id),first={...base,id:'legacy-a',status:'approved',updatedAt:'2026-01-06T00:00:00Z',payload:{...base.payload,inAt:'2026-01-05T09:00:00+08:00'}},second={...first,id:'legacy-b',payload:{...first.payload,inAt:'2026-01-05T10:00:00+08:00'}},records=[...ctx.records,first,second];let report=rules.attendanceReport(records,'2026-01-07T00:00:00Z')[0];assert.equal(report.correctionConflict,true);assert.equal(report.uncoveredMinutes,null);assert.equal(report.inAt,null);assert.equal(report.status,'补卡冲突待核验');assert.equal(rules.attendanceReport([...records].reverse(),'2026-01-07T00:00:00Z')[0].uncoveredMinutes,null);const equivalent={...first,id:'legacy-equivalent',payload:{...first.payload,inAt:'2026-01-05T01:00:00Z',outAt:'2026-01-05T10:00:00Z'}};assert.equal(rules.correctionResolution([...ctx.records,first,equivalent],shift.id).conflict,false);const approved=rules.applyAttendance(records,ctx.state,ctx.member,{action:'decideCorrection',id:pending.id,accepted:true,evidence:'依据新证据独立核实真实出勤并形成新版本'},'2026-01-06T00:00:00Z');report=rules.attendanceReport(records.filter(r=>r.id!==pending.id).concat(approved),'2026-01-07T00:00:00Z')[0];assert.equal(report.correctionVersion,1);assert.equal(report.correctionConflict,false);assert.equal(report.uncoveredMinutes,60);const later={...approved,id:'newer-version',payload:{...approved.payload,version:2,inAt:'2026-01-05T09:00:00+08:00'}};report=rules.attendanceReport([later,...records,approved],'2026-01-07T00:00:00Z')[0];assert.equal(report.correctionVersion,2);assert.equal(report.uncoveredMinutes,0);sqlite.close();
});

