test('P2/P3 北京时间业务日：跨年评估、发展与学习截止日和日期合法性',async()=>{
 const {sqlite,e}=await setup();const standard=await send({action:'standard',code:'CN-DATE-STANDARD',name:'业务日期能力',anchors}),course=await send({action:'course',code:'CN-DATE-COURSE',title:'跨年日期课程',description:'用于验证学习截止日采用北京时间',content:'学习任务按照北京时间截止日期安排，不能因为UTC日期较早而接受已经过期的任务。'});await send({action:'publishCourse',id:course.id});const ctx=await (await import('../lib/hris/development-repository.ts')).developmentContext(),rules=await import('../lib/hris/development.ts'),time=await import('../lib/hris/business-time.ts'),workforce=await import('../lib/hris/workforce.ts');assert.equal(workforce.businessDate,time.businessDate);assert.equal(time.businessDate('2026-12-31T15:59:59Z'),'2026-12-31');assert.equal(time.businessDate('2026-12-31T16:00:00Z'),'2027-01-01');assert.equal(time.businessDate('2027-01-01T00:00:00+08:00'),'2027-01-01');assert.equal(time.businessDate('2028-02-28T16:00:00Z'),'2028-02-29');
 const apply=(command,at)=>rules.applyDevelopment(ctx.records,ctx.state,ctx.member,command,at),assessment={action:'assessment',employeeId:e.id,standardId:standard.id,rating:3,evidence:'跨年当日根据工作事实进行能力评估',assessedOn:'2027-01-01'};assert.throws(()=>apply(assessment,'2026-12-31T15:59:59Z'),/评估日期不能在未来/);assert.equal(apply(assessment,'2026-12-31T16:00:00Z').payload.assessedOn,'2027-01-01');const plan={action:'plan',employeeId:e.id,standardId:standard.id,target:3,title:'跨年发展计划',actionPlan:'按截止日期完成指定能力发展任务',due:'2026-12-31'};assert.equal(apply(plan,'2026-12-31T15:59:59Z').payload.due,'2026-12-31');assert.throws(()=>apply(plan,'2026-12-31T16:00:00Z'),/截止日期不能早于今天/);assert.equal(apply({...plan,due:'2027-01-01'},'2026-12-31T16:00:00Z').payload.due,'2027-01-01');const enroll={action:'enroll',employeeId:e.id,courseId:course.id,due:'2026-12-31'};assert.throws(()=>apply(enroll,'2026-12-31T16:00:00Z'),/学习截止日期不能早于今天/);assert.equal(apply({...enroll,due:'2027-01-01'},'2026-12-31T16:00:00Z').payload.due,'2027-01-01');assert.throws(()=>apply({...plan,due:'2027-02-29'},'2026-12-31T16:00:00Z'));sqlite.close();
});

test('P2/P3 薪酬独立复核：移除作者、移除人及历史提交者不可绕过角色隔离',async()=>{
 const {sqlite,e,org}=await setup();for(const id of ['oldWriter','remover','oldSubmitter'])await grant(id,'payroll_editor',null,[org.id]);await grant('cleanReviewer','payroll_reviewer',null,[org.id]);const b=await pay({action:'batch',name:'薪酬参与记录核验',orgId:org.id,period:'2026-09',currency:'CNY',policyReference:'合成薪酬核对规则，保留完整编制参与人'}),items=[{name:'核定工资',category:'earning',amountCents:100000,source:'合成核定薪资来源，不含真实人员数据'}];act('oldWriter');const old=await pay({action:'slip',batchId:b.id,employeeId:e.id,items});act('remover');await pay({action:'removeSlip',id:old.id,reason:'原明细需重建，移除动作仍是编制参与'});act('owner');await pay({action:'slip',batchId:b.id,employeeId:e.id,items});act('oldSubmitter');await pay({action:'submit',id:b.id,evidence:'初次提交本期工资批次供独立核验'});act('cleanReviewer');await pay({action:'return',id:b.id,evidence:'请重新核对批次说明后再次提交'});act('owner');await pay({action:'submit',id:b.id,evidence:'本次由其他编制人员重新提交核验'});
 // Model legacy payloads that omitted contributors; immutable operation events still exist.
 for(const id of [old.id,b.id]){const row=sqlite.prepare('SELECT payload FROM hris_development_records WHERE id=?').get(id),payload=JSON.parse(row.payload);delete payload.contributors;sqlite.prepare('UPDATE hris_development_records SET payload=? WHERE id=?').run(JSON.stringify(payload),id);}
 for(const id of ['oldWriter','remover','oldSubmitter']){await grant(id,'payroll_reviewer',null,[org.id],true);act(id);await pay({action:'approve',id:b.id,evidence:'历史编制参与者改为复核角色仍不可自审'},403);await pay({action:'return',id:b.id,evidence:'移除记录或重新提交不得清除参与记录'},403);assert.ok(!(await queue()).items.some(r=>r.recordId===b.id&&r.action==='工资批次复核'));}
 act('cleanReviewer');assert.ok((await queue()).items.some(r=>r.recordId===b.id&&r.action==='工资批次复核'));const d=await expect(await payroll.GET()),rules=await import('../lib/hris/payroll-review.ts');assert.equal(rules.payrollBatchIndependent(d.records.find(r=>r.id===b.id),d.records,{userId:'oldWriter',employeeId:null}),false);assert.equal(rules.payrollBatchIndependent(d.records.find(r=>r.id===b.id),d.records,{userId:'cleanReviewer',employeeId:null}),true);await pay({action:'approve',id:b.id,evidence:'未参与编制和提交的独立复核人员批准'});act('owner');await pay({action:'publish',id:b.id,evidence:'完成独立核验后正式发布本人工资条'});act('employee');const mine=await expect(await payroll.GET());assert.equal(mine.records.length,1);assert.equal(mine.records[0].payload.contributors,undefined);assert.equal(mine.records[0].payload.netCents,100000);sqlite.close();
});

