 await pay({action:'submit',id:b.id,evidence:'核实本期合成金额提交独立复核'});act('reportChecker');await pay({action:'approve',id:b.id,evidence:'独立核验合成金额全部正确'});assert.equal((await expect(await report('payrollReconciliation'))).total,0);act('owner');await pay({action:'publish',id:b.id,evidence:'发布已核定合成工资条用于对账'});
