test('P3 自助绩效待办：目标调整阻塞与申请可见、退回跟进版本及任务导航',async()=>{
 const {sqlite,plan,goals}=await goalChangeFixture();act('employee');const self=async()=>expect(await selfService.GET());assert.ok((await self()).tasks.some(t=>t.id===plan.id));const log=await checkin({action:'submit',planId:plan.id,goalIndex:0,progress:20,evidence:'合成阶段成果已提交供管理者反馈',actionPlan:'根据核验反馈补充下一步行动'});act('manager');await checkin({action:'feedback',id:log.id,accepted:false,evidence:'请补充阶段结果的可验证依据'});act('employee');assert.ok((await self()).tasks.some(t=>t.id===log.id&&t.href==='/performance-checkins'));const a=await goalChange({action:'request',planId:plan.id,goals:[{...goals[0],title:'修订后的交付目标'}],evidence:'调整目标范围后重新确认实施依据'});let d=await self();assert.ok(!d.tasks.some(t=>[plan.id,log.id].includes(t.id)));assert.equal(d.requests.find(r=>r.id===a.id).status,'submitted');assert.equal(d.requests.find(r=>r.id===a.id).href,'/performance-changes');await perf({action:'selfReview',id:plan.id,evidence:'待审调整时不得误导员工继续提交'},400);await goalChange({action:'withdraw',id:a.id,evidence:'暂缓目标调整，先完成原目标核对'});d=await self();assert.ok(d.tasks.some(t=>t.id===plan.id));assert.ok(d.tasks.some(t=>t.id===log.id));assert.equal(d.requests.find(r=>r.id===a.id).status,'withdrawn');const next=await goalChange({action:'request',planId:plan.id,goals:[{...goals[0],title:'最新确认交付目标'}],evidence:'补充业务依据后重新提交目标调整'});act('manager');await goalChange({action:'review',id:next.id,accepted:true,evidence:'独立核实业务变化并批准新版目标'});assert.equal((await self()).requests.length,0);act('employee');d=await self();assert.ok(d.tasks.some(t=>t.id===plan.id));assert.ok(!d.tasks.some(t=>t.id===log.id));assert.equal(d.requests.find(r=>r.id===next.id).status,'approved');await perf({action:'selfReview',id:plan.id,evidence:'按新版目标提交本人工作结果说明'});assert.ok(!(await self()).tasks.some(t=>t.id===plan.id));sqlite.close();
});

