test('P3 学习任务恢复：保留考试次数和历史，重新提交，范围与项目状态重新检查',async()=>{
 const {sqlite,e}=await setup();
 const course=await send({action:'course',code:'RECOVER',title:'恢复课程',description:'合成数据恢复流程测试',content:'合成课程内容用于验证取消后的恢复不会重置考试次数和历史记录。'});
 await send({action:'exam',courseId:course.id,questions:[{prompt:'请选择正确的合成测试答案',options:['正确','错误'],correct:0}],passingScore:100,maxAttempts:1});
 await send({action:'publishCourse',id:course.id});
 const task=await send({action:'enroll',employeeId:e.id,courseId:course.id,due});
 act('employee');await send({action:'attemptExam',enrollmentId:task.id,answers:[1]});
 act('manager');await send({action:'cancelEnrollment',id:task.id,reason:'员工排期调整暂时取消任务'});
 const revision=(await get()).revision;
 act('employee');await send({action:'restoreEnrollment',id:task.id,due,evidence:'本人尝试未经管理者恢复任务'},403);
 act('manager');await send({action:'restoreEnrollment',id:task.id,due:'2020-01-01',evidence:'恢复日期不能早于当前日期'},400);
 await send({action:'restoreEnrollment',id:task.id,due,evidence:'排期已经恢复继续原任务学习'});
 await send({action:'restoreEnrollment',id:task.id,due,evidence:'重复恢复不能覆盖当前记录'},400);
 assert.equal((await get()).records.find(r=>r.id===task.id).status,'active');
 act('employee');await send({action:'attemptExam',enrollmentId:task.id,answers:[0]},400);await send({action:'submitLearning',id:task.id,evidence:'恢复不应该绕过原有考试门槛'},400);
 act('owner');const history=await expect(await dev.GET(request('/api/development?id='+task.id)));assert.ok(history.items.some(x=>x.snapshot.status==='cancelled'));assert.ok(history.items.some(x=>x.snapshot.payload.restoredBy==='manager'));assert.equal((await get()).revision,revision+1);
 const org=(await expect(await hris.GET())).state.orgs.find(o=>o.name==='研发');
 const simple=await send({action:'course',code:'RECOVER2',title:'成果恢复课程',description:'恢复后必须重新提交成果',content:'合成课程内容用于验证旧成果保留历史而不直接进入已核验完成状态。'});await send({action:'publishCourse',id:simple.id});
 const training=await send({action:'training',name:'恢复项目',orgId:org.id,period:'恢复测试',start:'2026-01-01',end:due,instructor:'合成讲师',courseIds:[simple.id]});await send({action:'publishTraining',id:training.id});
 const second=await send({action:'enroll',trainingId:training.id,employeeId:e.id,courseId:simple.id,due});
 act('employee');await send({action:'submitLearning',id:second.id,evidence:'取消之前提交的成果证据'});
 act('manager');await send({action:'cancelEnrollment',id:second.id,reason:'材料需要重新补充后再学习'});await send({action:'restoreEnrollment',id:second.id,due,evidence:'材料已备齐恢复原有学习任务'});
 assert.equal((await get()).records.find(r=>r.id===second.id).payload.submittedBy,undefined);await send({action:'verifyLearning',id:second.id,accepted:true,evidence:'尚未重新提交不能直接核验'},400);
 await send({action:'cancelEnrollment',id:second.id,reason:'项目调整取消并结束项目'});await send({action:'closeTraining',id:training.id});await send({action:'restoreEnrollment',id:second.id,due,evidence:'已结束项目不允许恢复任务'},400);
 assert.ok((await expect(await dev.GET(request('/api/development?id='+second.id)))).items.some(x=>x.snapshot.payload.evidence==='取消之前提交的成果证据'));sqlite.close();
});

test('P3 在职合同登记覆盖：无记录人员、当日边界、草稿与未来登记不充当覆盖',async()=>{
 const {sqlite,e,other,otherOrg}=await setup();const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});
 const query=()=>reports.GET(request('/api/reports?dataset=contractCoverage'));
 let data=await expect(await query());assert.equal(data.total,2);assert.ok(data.rows.every(r=>r[7]===0));
 async function contract(number,start,end,sign=true){const c=await work({action:'contract',employeeId:e.id,number,employerName:'合成主体'+number,contractType:end?'fixed':'open',start,...(end?{end}:{}),evidence:'PRIVATE_COVERAGE_EVIDENCE 合成登记凭证'});if(sign)await work({action:'signContract',id:c.id,signedOn:'2020-01-01',evidence:'PRIVATE_COVERAGE_EVIDENCE 合成签署事实'});return c;}
 await contract('BOUNDARY',today,today);await contract('FUTURE','2099-01-01','2099-12-31');await contract('EXPIRED','2020-01-01','2020-12-31');await contract('DRAFT','2020-01-01',undefined,false);const cancelled=await contract('CANCELLED','2020-01-01',undefined,false);await work({action:'cancelContract',id:cancelled.id,evidence:'取消合成草稿以验证不计数'});
 data=await expect(await query());const row=data.rows.find(r=>r[1]===e.code);assert.equal(row[0],today);assert.deepEqual(row.slice(7),[1,'BOUNDARY',1,1,0,1]);assert.equal(data.rows.find(r=>r[1]===other.code)[7],0);assert.ok(!JSON.stringify(data).includes('PRIVATE_COVERAGE_EVIDENCE'));
 const open=await contract('OPEN','2020-01-01');assert.equal((await expect(await query())).rows.find(r=>r[1]===e.code)[7],2);act('hr');await work({action:'endContract',id:open.id,endedOn:today,evidence:'独立核实合成合同终止事实'});data=await expect(await query());assert.equal(data.total,1);assert.equal(data.rows[0][7],1);assert.equal(data.rows[0][11],1);
 await grant('coverageOther','hr',null,[otherOrg.id]);act('coverageOther');data=await expect(await query());assert.equal(data.total,1);assert.equal(data.rows[0][1],other.code);assert.equal(data.rows[0][7],0);
 act('employee');await expect(await query(),403);await expect(await reports.POST(request('/api/reports',{revision:data.revision,query:{dataset:'contractCoverage'}})),403);sqlite.close();
});

test('P3 合同协议类别与期限独立：保留旧数据未知状态，不由期限推断协议类别',async()=>{
 const {sqlite,e}=await setup();const input={action:'contract',employeeId:e.id,employerName:'合成分类主体',contractType:'fixed',start:'2026-01-01',end:'2026-12-31',evidence:'合成资料明确区分协议类别与期限类型'};
 const old=await work({...input,number:'LEGACY-CATEGORY'});assert.equal((await get()).records.find(r=>r.id===old.id).payload.agreementCategory,undefined);
 const labor=await work({...input,number:'LABOR-CATEGORY',agreementCategory:'labor'});assert.equal((await get()).records.find(r=>r.id===labor.id).payload.agreementCategory,'labor');
 await work({...input,number:'SERVICE-CATEGORY',agreementCategory:'service'});await work({...input,number:'INTERN-CATEGORY',agreementCategory:'internship'});await work({...input,number:'INVALID-CATEGORY',agreementCategory:'fixed'},400);
 const report=await expect(await reports.GET(request('/api/reports?dataset=contractOperations')));assert.equal(report.columns[6],'期限类型');assert.equal(report.columns[15],'协议类别');assert.deepEqual(report.rows.map(r=>r[15]),['待登记','劳动合同','劳务合同','实习协议']);assert.ok(report.rows.every(r=>r[6]==='固定期限'));await work({action:'classifyContract',id:old.id,agreementCategory:'labor',evidence:'核对原始凭证后补充草稿类别'});await work({action:'signContract',id:old.id,signedOn:'2026-01-01',evidence:'核对实际签署资料完成登记'});await work({action:'classifyContract',id:old.id,agreementCategory:'service',evidence:'已签署记录不能直接改类别'},400);const history=await expect(await dev.GET(request('/api/development?id='+old.id)));assert.ok(history.items.some(x=>x.snapshot.payload.categoryEvidence==='核对原始凭证后补充草稿类别'));sqlite.close();
});

test('P2/P3 附件读取撤权一致性：列表同批校验，文件读取后再次检查修订',async()=>{
 const {db,sqlite,e,org}=await setup();const objects=mockBucket();const file=await expect(await upload(e.id,'%PDF-revocation',undefined,{visibility:'employee'}));
 const original=globalThis.p2env.BUCKET.get;act('employee');globalThis.p2env.BUCKET.get=async key=>{const result=await original(key);sqlite.exec("UPDATE hris_memberships SET active=0 WHERE user_id='employee'; UPDATE hris_workspaces SET revision=revision+1");return result;};await expect(await files.GET(request('/api/attachments?id='+file.id)),409);assert.equal(objects.size,1);globalThis.p2env.BUCKET.get=original;
 act('owner');await grant('attachmentScoped','hr',null,[org.id]);act('attachmentScoped');let revoked=false;globalThis.p2env.DB={...db,batch:async statements=>{if(!revoked&&statements.some(s=>s.sql.includes('FROM hris_attachments'))){revoked=true;sqlite.exec("UPDATE hris_memberships SET org_scope='[]' WHERE user_id='attachmentScoped'; UPDATE hris_workspaces SET revision=revision+1");}return db.batch(statements);}};
 await expect(await files.GET(request('/api/attachments?employeeId='+e.id)),409);globalThis.p2env.DB=db;await expect(await files.GET(request('/api/attachments?employeeId='+e.id)),403);await expect(await files.GET(request('/api/attachments?id='+file.id)),403);sqlite.close();
});

test('P2/P3 成员目录撤权一致性：读取授权名单期间管理员降权不返回旧权限下的名单',async()=>{
 const {db,sqlite}=await setup();await grant('memberReader','admin',null);act('memberReader');assert.ok((await expect(await members.GET())).members.length>0);let once=true;globalThis.p2env.DB={...db,batch:async statements=>{if(once&&statements.some(s=>s.sql.startsWith('SELECT email,name,role'))){once=false;sqlite.exec("UPDATE hris_memberships SET role='hr' WHERE user_id='memberReader'; UPDATE hris_workspaces SET revision=revision+1");}return db.batch(statements);}};await expect(await members.GET(),409);globalThis.p2env.DB=db;await expect(await members.GET(),403);act('owner');assert.ok((await expect(await members.GET())).members.length>0);sqlite.close();
});

test('P3 学分到期：授予快照、北京时间当日边界及撤销后不重复扣到期',async()=>{
 const {sqlite,e}=await setup(),logic=await import('../lib/hris/learning-credits.ts'),repository=await import('../lib/hris/development-repository.ts');
 const course=await send({action:'course',code:'EXPIRING-CREDIT',title:'有效期课程',description:'合成学分有效期规则测试',content:'合成课程内容用于验证学分到期保存授予规则快照，不改变学习完成结果。'});
 await credit({action:'policy',courseId:course.id,creditUnits:125,validityDays:0,evidence:'有效天数不能为零或小数'},400);await credit({action:'policy',courseId:course.id,creditUnits:125,validityDays:1,evidence:'独立设计授予登记日为第一有效日'});await send({action:'publishCourse',id:course.id});const enrollment=await send({action:'enroll',employeeId:e.id,courseId:course.id,due});act('employee');await send({action:'submitLearning',id:enrollment.id,evidence:'完成合成课程实践并提交证据'});act('manager');await send({action:'verifyLearning',id:enrollment.id,accepted:true,evidence:'独立核实合成学习成果通过'});act('owner');
 const ctx=await repository.developmentContext(),award=logic.applyLearningCredit(ctx.records,ctx.state,ctx.member,{action:'award',enrollmentId:enrollment.id,evidence:'登记合成到期学分以核对时区'},'2026-12-31T16:05:00Z');assert.equal(award.payload.awardedOn,'2027-01-01');assert.equal(award.payload.validUntil,'2027-01-01');assert.equal(award.payload.validityDays,1);
 let records=[...ctx.records,award],summary=logic.learningCreditSummary(records,'2027-01-01')[0];assert.equal(summary.availableUnits,125);assert.equal(summary.expiredUnits,0);summary=logic.learningCreditSummary(records,'2027-01-02')[0];assert.equal(summary.expiredUnits,125);assert.equal(summary.netUnits,125);assert.equal(summary.availableUnits,0);
 act('hr');const reviewer=await repository.developmentContext();const reversal=logic.applyLearningCredit(records,reviewer.state,reviewer.member,{action:'reverse',awardId:award.id,evidence:'独立核实已到期学分登记有误'},'2027-01-02T03:00:00Z');summary=logic.learningCreditSummary([...records,reversal],'2027-01-02')[0];assert.deepEqual([summary.awardedUnits,summary.reversedUnits,summary.expiredUnits,summary.availableUnits],[125,125,0,0]);assert.equal(records.find(r=>r.id===enrollment.id).status,'completed');sqlite.close();
});

test('P3 人员经历：HR范围、本人只读、月份校验及更正作废保留历史',async()=>{
 const {sqlite,e,other}=await setup(),route=await import('../app/api/employee-experiences/route.ts');
 const read=()=>route.GET(),write=async(command,status=200,revision)=>(expect(await route.POST(request('/api/employee-experiences',{revision:revision??(await get()).revision,command})),status));
 const input={action:'save',employeeId:e.id,category:'education',institution:'合成学校',title:'合成专业',startMonth:'2020-09',endMonth:'2024-06',ongoing:false,description:'合成教育经历用于验证字段和权限',evidence:'依据合成资料登记教育经历'};
 await write({...input,startMonth:'2020-13'},400);await write({...input,endMonth:'2019-01'},400);await write({...input,ongoing:true},400);await write({...input,endMonth:undefined},400);await write({...input,startMonth:'2099-01',endMonth:'2099-12'},400);
 act('hr');await write({...input,employeeId:other.id},403);const first=await write(input);await write(input,400);let current=await expect(await read());assert.equal(current.records[0].payload.version,1);assert.equal(current.employees.length,1);
 act('employee');assert.equal((await expect(await read())).records.length,1);assert.ok((await get()).records.some(r=>r.id===first.id));await write({...input,id:first.id,title:'本人不能改写HR登记'},403);act('manager');assert.equal((await expect(await read())).records.length,0);await expect(await dev.GET(request('/api/development?id='+first.id)),403);
 act('owner');const revision=(await get()).revision;await write({...input,id:first.id,title:'更正后的合成专业',evidence:'重新核实合成资料后更正名称'});await write({...input,id:first.id,title:'过期修订不应覆盖最新记录'},409,revision);await write({...input,id:first.id,employeeId:other.id},400);await write({...input,id:first.id,category:'employment'},400);
 const job=await write({...input,category:'employment',title:'合成岗位',institution:'合成单位',startMonth:'2024-01',endMonth:undefined,ongoing:true});assert.equal((await expect(await read())).records.find(r=>r.id===job.id).payload.ongoing,true);
 await write({action:'cancel',id:first.id,evidence:'资料重复作废并保留办理历史'});await write({...input,id:first.id},400);act('employee');const history=await expect(await dev.GET(request('/api/development?id='+first.id)));assert.equal(history.items.length,3);assert.ok(history.items.some(i=>i.snapshot.payload.title==='合成专业'));assert.ok(history.items.some(i=>i.snapshot.payload.title==='更正后的合成专业'));assert.equal((await expect(await read())).records.find(r=>r.id===first.id).status,'cancelled');sqlite.close();
});

test('P3 经历关联人才档案：HR可见有效摘要，普通经理不扩展经历权限',async()=>{
 const {sqlite,e,otherOrg}=await setup(),experiences=await import('../app/api/employee-experiences/route.ts'),profiles=await import('../app/api/cadre-profiles/route.ts');const record=await expect(await experiences.POST(request('/api/employee-experiences',{revision:(await get()).revision,command:{action:'save',employeeId:e.id,category:'employment',institution:'合成经历机构',title:'EXPERIENCE_PROFILE_ROLE_CHECK',startMonth:'2020-01',endMonth:'2021-01',ongoing:false,description:'合成经历只用于核对聚合档案权限',evidence:'合成凭证不应在摘要中显示'}})));
 const profile=()=>profiles.GET(request('/api/cadre-profiles?employeeId='+e.id));let d=await expect(await profile());const section=d.sections.find(s=>s.key==='experiences');assert.equal(section.items.length,1);assert.equal(section.items[0].status,'资料登记，未代表外部核验');assert.ok(!JSON.stringify(d).includes('合成凭证不应在摘要中显示'));act('manager');d=await expect(await profile());assert.ok(!d.sections.some(s=>s.key==='experiences'));assert.ok(!JSON.stringify(d).includes('EXPERIENCE_PROFILE_ROLE_CHECK'));act('employee');await expect(await profile(),403);
 await grant('experienceOutside','hr',null,[otherOrg.id]);act('experienceOutside');await expect(await profile(),403);act('owner');await expect(await experiences.POST(request('/api/employee-experiences',{revision:(await get()).revision,command:{action:'cancel',id:record.id,evidence:'作废经历在有效摘要中排除'}})));assert.equal((await expect(await profile())).sections.find(s=>s.key==='experiences').items.length,0);sqlite.close();
});
